const cases = [
  { prompt: 'Audit this existing checkout UI', shouldActivate: true },
  { prompt: 'Build a new checkout page', shouldActivate: false },
  { prompt: 'Use frontend-production-review on this diff', shouldActivate: true },
];

for (const testCase of cases) {
  const result = await runAgent(testCase.prompt);
  expect(result.activatedSkills.includes('frontend-production-review'))
    .toBe(testCase.shouldActivate);
}
